-- Owner-controlled write barrier shared by every deployed Worker version.
-- No application API may update this row. Freeze drains prior transactions.
CREATE TABLE operation_control(id INTEGER PRIMARY KEY CHECK(id=1),writes_paused INTEGER NOT NULL CHECK(writes_paused IN(0,1)));
INSERT INTO operation_control VALUES(1,0);
CREATE TRIGGER freeze_classes_insert BEFORE INSERT ON classes WHEN (SELECT writes_paused FROM operation_control WHERE id=1)=1 BEGIN SELECT RAISE(ABORT,'OKGU_WRITE_PAUSED'); END;
CREATE TRIGGER freeze_classes_update BEFORE UPDATE ON classes WHEN (SELECT writes_paused FROM operation_control WHERE id=1)=1 BEGIN SELECT RAISE(ABORT,'OKGU_WRITE_PAUSED'); END;
CREATE TRIGGER freeze_classes_delete BEFORE DELETE ON classes WHEN (SELECT writes_paused FROM operation_control WHERE id=1)=1 BEGIN SELECT RAISE(ABORT,'OKGU_WRITE_PAUSED'); END;
